import os
import random
import struct
from typing import List, Tuple

# This generator produces valid WSON-like payload bytes tailored to the provided fuzzing stubs.
# It avoids malformed constructs and stays under 4096 bytes.

WSON_NULL_TYPE = 0x00
WSON_BOOLEAN_TYPE_FALSE = 0x01
WSON_BOOLEAN_TYPE_TRUE = 0x02
WSON_NUMBER_INT_TYPE = 0x10
WSON_NUMBER_FLOAT_TYPE = 0x11
WSON_NUMBER_LONG_TYPE = 0x12
WSON_NUMBER_DOUBLE_TYPE = 0x13
WSON_STRING_TYPE = 0x20
WSON_UINT8_STRING_TYPE = 0x21
WSON_NUMBER_BIG_INT_TYPE = 0x22
WSON_NUMBER_BIG_DECIMAL_TYPE = 0x23
WSON_MAP_TYPE = 0x30
WSON_ARRAY_TYPE = 0x31
WSON_EXTEND_TYPE = 0x40

# Little-endian packers

def u32(n: int) -> bytes:
    return struct.pack('<I', n & 0xFFFFFFFF)

def i32(n: int) -> bytes:
    # struct handles range checking; do not mask signed values
    return struct.pack('<i', int(n))

def u64(n: int) -> bytes:
    return struct.pack('<Q', n & 0xFFFFFFFFFFFFFFFF)

def i64(n: int) -> bytes:
    return struct.pack('<q', int(n))

def f32(x: float) -> bytes:
    return struct.pack('<f', float(x))

def f64(x: float) -> bytes:
    return struct.pack('<d', float(x))

# Content generators

def rand_utf8(rng: random.Random, max_len: int) -> bytes:
    # Generate valid UTF-8 with mixed ranges, up to max_len bytes
    if max_len <= 0:
        return b""
    choices = [chr(c) for c in range(0x20, 0x7F)]
    choices += ['\t', '\n', '\r', ' ', '"', '\\']
    multiranges = [
        (0x00A1, 0x00FF),
        (0x0100, 0x017F),
        (0x0400, 0x04FF),
        (0x0370, 0x03FF),
        (0x4E00, 0x4F8F),
        (0x20AC, 0x20AC),
        (0x1F600, 0x1F64F),
    ]
    target = rng.randint(0, max_len)
    s: List[str] = []
    while True:
        b = ''.join(s).encode('utf-8')
        if len(b) >= target:
            return b[:target]
        if rng.random() < 0.7:
            s.append(rng.choice(choices))
        else:
            lo, hi = rng.choice(multiranges)
            s.append(chr(rng.randint(lo, hi)))


def rand_bytes(rng: random.Random, max_len: int) -> bytes:
    if max_len <= 0:
        return b""
    ln = rng.randint(0, max_len)
    if ln == 0:
        return b""
    if rng.random() < 0.4:
        # Segmented mixture
        parts: List[bytes] = []
        remaining = ln
        while remaining > 0:
            seg = rng.randint(1, min(32, remaining))
            kind = rng.random()
            if kind < 0.25:
                parts.append(os.urandom(seg))
            elif kind < 0.5:
                parts.append(bytes([rng.randrange(256)]) * seg)
            elif kind < 0.75:
                parts.append(rand_utf8(rng, seg))
            else:
                parts.append(bytes(rng.randrange(256) for _ in range(seg)))
            remaining -= seg
        return b"".join(parts)[:ln]
    elif rng.random() < 0.7:
        return rand_utf8(rng, ln)
    else:
        # Simple patterns
        return rng.choice([b"\x00"*ln, b"\xFF"*ln, b"A"*ln, (b"\x00\xFF"*(ln//2)) + (b"\x00" if ln%2 else b"")])

# WSON builders

def wson_string(rng: random.Random, max_payload: int = 512) -> bytes:
    payload = rand_utf8(rng, max_payload)
    return bytes([WSON_STRING_TYPE]) + i32(len(payload)) + payload


def wson_uint8_string(rng: random.Random, max_payload: int = 512) -> bytes:
    payload = rand_bytes(rng, max_payload)
    return bytes([WSON_UINT8_STRING_TYPE]) + i32(len(payload)) + payload


def wson_extend(rng: random.Random, max_payload: int = 512) -> bytes:
    payload = rand_bytes(rng, max_payload)
    return bytes([WSON_EXTEND_TYPE]) + i32(len(payload)) + payload


def wson_string_length_then_bytes(rng: random.Random, max_payload: int = 512) -> bytes:
    payload = rand_utf8(rng, max_payload)
    # Same wire form as push_type_string followed by payload bytes
    return bytes([WSON_STRING_TYPE]) + i32(len(payload)) + payload


def wson_property_map_single(rng: random.Random) -> bytes:
    key = rand_utf8(rng, 128)
    b = bytearray()
    b.append(WSON_MAP_TYPE)
    b += u32(1)
    b.append(WSON_STRING_TYPE)
    b += i32(len(key))
    b += key
    b.append(WSON_NULL_TYPE)
    return bytes(b)


def wson_number(rng: random.Random) -> bytes:
    choice = rng.choice(['i32', 'i64', 'f32', 'f64'])
    if choice == 'i32':
        return bytes([WSON_NUMBER_INT_TYPE]) + i32(rng.randint(-2**31, 2**31 - 1))
    if choice == 'i64':
        # Avoid bit-masking; give a valid int64 in range
        n = rng.randint(-2**63 + 1, 2**63 - 1)  # exclude exact -2**63 to avoid edge in some libs
        return bytes([WSON_NUMBER_LONG_TYPE]) + i64(n)
    if choice == 'f32':
        vals = [0.0, -0.0, 1.0, -1.0, 3.14159, float('inf'), float('-inf'), rng.uniform(-1e6, 1e6)]
        v = rng.choice(vals)
        return bytes([WSON_NUMBER_FLOAT_TYPE]) + f32(v)
    vals = [0.0, -0.0, 1.0, -1.0, 3.1415926535, float('inf'), float('-inf'), rng.uniform(-1e12, 1e12)]
    v = rng.choice(vals)
    return bytes([WSON_NUMBER_DOUBLE_TYPE]) + f64(v)


def wson_bool(rng: random.Random) -> bytes:
    return bytes([WSON_BOOLEAN_TYPE_TRUE if rng.random() < 0.5 else WSON_BOOLEAN_TYPE_FALSE])


def wson_string_like_numeric(rng: random.Random) -> bytes:
    txt = str(rng.choice([0, 1, -1, 42, -273, 2147483647, -2147483648, 3.14159, -0.0001, 1e9]))
    payload = txt.encode('utf-8')
    t = rng.choice([WSON_STRING_TYPE, WSON_UINT8_STRING_TYPE, WSON_NUMBER_BIG_INT_TYPE, WSON_NUMBER_BIG_DECIMAL_TYPE])
    return bytes([t]) + i32(len(payload)) + payload


def wson_array(rng: random.Random, budget: int) -> bytes:
    items: List[bytes] = []
    max_items = min(6, max(0, budget // 8))
    n = rng.randint(0, max_items) if max_items > 0 else 0
    for _ in range(n):
        item = wson_value(rng, max(8, budget // max(1, n)))
        items.append(item)
    b = bytearray()
    b.append(WSON_ARRAY_TYPE)
    b += u32(len(items))
    for it in items:
        b += it
    return bytes(b)


def wson_map(rng: random.Random, budget: int) -> bytes:
    entries: List[Tuple[bytes, bytes]] = []
    max_items = min(6, max(0, budget // 16))
    n = rng.randint(0, max_items) if max_items > 0 else 0
    for _ in range(n):
        key = rand_utf8(rng, 32)
        key_field = bytes([WSON_STRING_TYPE]) + i32(len(key)) + key
        val = wson_value(rng, max(8, budget // max(1, n)))
        entries.append((key_field, val))
    b = bytearray()
    b.append(WSON_MAP_TYPE)
    b += u32(len(entries))
    for k, v in entries:
        b += k
        b += v
    return bytes(b)


def wson_value(rng: random.Random, budget: int) -> bytes:
    choices = [
        lambda: wson_string(rng, min(64, budget)),
        lambda: wson_uint8_string(rng, min(64, budget)),
        lambda: wson_extend(rng, min(64, budget)),
        lambda: wson_string_length_then_bytes(rng, min(64, budget)),
        lambda: wson_number(rng),
        lambda: wson_bool(rng),
        lambda: bytes([WSON_NULL_TYPE]),
        lambda: wson_property_map_single(rng),
        lambda: wson_string_like_numeric(rng),
        lambda: wson_array(rng, max(32, budget // 2)),
        lambda: wson_map(rng, max(32, budget // 2)),
    ]
    weights = [10, 8, 5, 7, 9, 6, 4, 3, 5, 4, 4]
    choice = rng.choices(choices, weights=weights, k=1)[0]
    return choice()


def build_blob_for_stub_family(rng: random.Random) -> bytes:
    parts: List[bytes] = []
    builders = [
        lambda: wson_string(rng, 200),
        lambda: wson_uint8_string(rng, 200),
        lambda: wson_extend(rng, 200),
        lambda: wson_string_length_then_bytes(rng, 200),
        lambda: wson_property_map_single(rng),
        lambda: wson_number(rng),
        lambda: wson_bool(rng),
        lambda: bytes([WSON_NULL_TYPE]),
        lambda: wson_array(rng, 128),
        lambda: wson_map(rng, 128),
    ]
    rng.shuffle(builders)
    for b in builders:
        chunk = b()
        parts.append(chunk)
        if sum(len(p) for p in parts) > 1024:
            break
    return b"".join(parts)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    strategy = rng.choices([0, 1, 2], weights=[5, 3, 2], k=1)[0]

    if strategy == 0:
        builder = rng.choice([
            lambda: wson_string(rng, 512),
            lambda: wson_uint8_string(rng, 512),
            lambda: wson_extend(rng, 512),
            lambda: wson_string_length_then_bytes(rng, 512),
            lambda: wson_property_map_single(rng),
            lambda: wson_number(rng),
            lambda: wson_bool(rng),
            lambda: bytes([WSON_NULL_TYPE]),
            lambda: wson_array(rng, 256),
            lambda: wson_map(rng, 256),
        ])
        blob = builder()
    elif strategy == 1:
        blob = build_blob_for_stub_family(rng)
    else:
        blob = rand_bytes(rng, 1024)

    return blob[:4096]
